// Source lint: the store check's role -> event-kind map is the matrix the
// relay-plane judge exports.
//
// `tooling/e2e/relay_planes.json` is generated by `haven-wire-planes
// --export` from the judge's own rows and pinned to them by a crate test, so
// it is the matrix every Rust layer judges by. The unproxied E2E lanes judge
// relay stores on the device, which cannot read the repo, so
// `plane_store_check.dart` carries a copy. A copy that drifted would let a
// lane pass a kind the judge forbids on that plane (or fail one it allows)
// while the wire layers disagree with it. Held here by equality.
//
// The store dump's limit is pinned beside it: `TestRelay.dumpStore` refuses
// an answer of exactly its limit as possibly truncated, which is sound only
// while the limit is the hermetic strfry's own cap (`haven-local-relay`'s half
// is `tooling/e2e/local-relay/tests/local_relay_store_dump.rs`).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import '../../integration_test/e2e/_lib/plane_store_check.dart';
import '../../integration_test/e2e/_lib/test_relay.dart';

void main() {
  test('every role admits exactly the event kinds the judge exports', () {
    final matrix =
        jsonDecode(
              File('../tooling/e2e/relay_planes.json').readAsStringSync(),
            )
            as Map<String, dynamic>;
    final roles = matrix['roles'] as Map<String, dynamic>;
    final exported = <String, Set<int>>{
      for (final entry in roles.entries)
        entry.key: <int>{
          for (final kind
              in (entry.value as Map<String, dynamic>)['events']
                  as List<dynamic>)
            kind as int,
        },
    };

    expect(exported, isNotEmpty, reason: 'the export lists no role');
    expect(
      kRoleEventKinds.keys.toSet(),
      exported.keys.toSet(),
      reason: 'the store check and the judge name different roles',
    );
    for (final role in exported.keys) {
      expect(
        kRoleEventKinds[role],
        exported[role],
        reason:
            'role $role admits other event kinds in plane_store_check.dart '
            'than in tooling/e2e/relay_planes.json; regenerate neither by '
            'hand — the export is the judge, so the copy follows it',
      );
    }
  });

  test("the store dump's limit is the hermetic strfry's filter cap", () {
    for (final conf in const <String>[
      '../tooling/e2e/strfry.conf',
      '../tooling/e2e/strfry-negentropy.conf',
    ]) {
      final cap = RegExp(
        r'^\s*maxFilterLimit\s*=\s*(\d+)\s*$',
        multiLine: true,
      ).firstMatch(File(conf).readAsStringSync());
      expect(cap, isNotNull, reason: '$conf sets no maxFilterLimit');
      expect(
        int.parse(cap!.group(1)!),
        kDumpStoreLimit,
        reason:
            '$conf caps a filter at another limit than TestRelay.dumpStore '
            'asks for: a dump truncated below its limit would read as the '
            'whole store',
      );
    }
  });
}
